import {readFile,writeFile,readdir} from 'node:fs/promises';
import {createHash} from 'node:crypto';
import assert from 'node:assert/strict';
const root='output/revisao-integral-20261119/servidor';
const notas={
 'supabase/functions/_shared/pix.mjs':['HMAC, tolerância de horário, beneficiário, moeda, valor, taxas e estornos verificados antes de aceitar um evento.','Mantido: remover consulta de confirmação ou validação encurtaria o caminho comprometendo a integridade financeira. Timeout de 18s e chave de idempotência já limitam a operação.'],
 'supabase/functions/_shared/cobranca.mjs':['Assinatura de webhook, preços configurados no servidor, versão de API e requisições com idempotência.','Mantido: timeout de 15s e validação da origem são necessários; operações financeiras não são paralelizadas sem dependência resolvida.'],
 'supabase/functions/webhook-pix/index.ts':['Confere HMAC, consulta a cobrança no provedor e aplica a atualização por RPC autenticada.','Mantido: o estado informado no webhook não substitui a confirmação do provedor; 503 permite nova tentativa quando a confirmação falha.'],
 'supabase/functions/webhook-cobranca/index.ts':['Limite de corpo, assinatura, reserva do evento e releitura da assinatura no provedor.','Mantido: reserva e liberação em finally evitam processamento concorrente duplicado. Sem chamadas reais de cobrança nesta revisão.'],
 'supabase/functions/cobranca-oficina/index.ts':['Autenticação do proprietário, reserva, cliente idempotente, consulta de assinatura e destino de retorno permitido.','Mantido: consultas sequenciais dependem de IDs e do estado atual; suprimi-las poderia gerar checkout duplicado.'],
 'supabase/functions/pix-os/index.ts':['Acesso financeiro da empresa conferido antes de criar/consultar cobrança; criação reservada com chave única.','Mantido: preservar autorização, reserva e confirmação do provedor é mais importante que uma antecipação especulativa de cobrança.'],
 'supabase/functions/fotos-proposta/index.ts':['Após validar token e RPC de acesso, assinava cada fotografia individualmente em sequência.','Alterado: delega a assinatura em lote. O gate de autorização, validade de 60s, 404/503 e contrato de resposta permanecem.'],
 'supabase/functions/fotos-proposta/assinar-fotos.mjs':['Não existia; a rotina sequencial ficava no handler.','Adicionado: elimina caminhos repetidos, limita cada lote a 100, relaciona resposta por caminho e recompõe ordem e legendas. Erro ou resposta incompleta rejeitam toda a galeria.'],
 'supabase/functions/automacoes-oficina/index.ts':['Segredo do agendador, canal configurado em HTTPS e permitido; reserva por aviso/canal antes do envio.','Mantido: timeout de 20s e estado incerto impedem reenvio automático potencialmente duplicado. Nenhuma mensagem externa enviada no teste.'],
 'supabase/functions/planejar-trajeto/index.ts':['Corpo limitado mesmo em stream, autenticação e gate de uso/permissão por RPC.','Mantido: o limite de 4096 bytes e o controle de acesso evitam trabalho desnecessário antes de chamar o provedor.'],
 'supabase/functions/planejar-trajeto/provedor.mjs':['Geocodificação e retornos independentes paralelos, timeout e sinal de cancelamento.','Mantido: já usa concorrência onde não há dependência. Coordenada ambígua continua exigindo escolha do usuário.'],
 'supabase/functions/calendario-externo/index.ts':['Feed por token validado; GET/HEAD, timeout de 12s, private/no-store.','Mantido: cache compartilhado poderia revelar agenda privada ou atrasar revogações.'],
 'supabase/functions/calendario-externo/ical.mjs':['Escapa texto, dobra linhas em 75 octetos UTF-8, usa UID/revisão e UTC, representa deslocamento separado.','Mantido: formato iCalendar já evita ambiguidade de datas; não reduzir a informação nem retirar escape por desempenho.'],
 'supabase/functions/recontatos-oleo/index.ts':['Entrada protegida por segredo de execução e reserva de trabalho.','Mantido: o handler é curto e encaminha uma operação reservada; não há lista de usuários carregada no frontend.'],
 'supabase/functions/recontatos-oleo/gerar.ts':['Previsão recebe dados numéricos, tem timeout e registra falha/conclusão. Resultado é sugestão revisável.','Mantido: preservar revisão e estados do job; não transforma previsão em mensagem automática.'],
 'supabase/functions/assistente-oficina/index.ts':['Autentica e reserva consumo; chamada de IA com timeout e store:false, registra resultado/falha.','Mantido: limites de consumo e timeout já delimitam o custo; não foi feita chamada paga ao provedor.'],
 'supabase/functions/capturar-atendimento/index.ts':['Limites de tamanho e tipo, autenticação, schema fechado, resposta sem persistir a fotografia.','Mantido: os limites e validação não devem ser removidos para reduzir latência. Tratamento de resposta antiga foi conferido no frontend.'],
 'supabase/functions/assistente-operacional/consultas-turno.mjs':['Cache restrito ao turno autenticado, máximo de três consultas simultâneas, cancelamento e métricas.','Mantido: já evita chamadas repetidas sem criar cache entre empresas ou usuários.'],
 'supabase/functions/assistente-operacional/provedor.mjs':['Retry limitado para erros recuperáveis com atraso e tempo total de execução.','Mantido: não reaplica gravações financeiras; logs não incluem conteúdo privado. Reduzir intervalo sem medir pode agravar limitação do provedor.'],
 'supabase/functions/assistente-operacional/index.ts':['Autenticação, leitura limitada do corpo, reserva do turno, transcrição e conversa com limite total de 105s.','Mantido: transcrição depende do áudio e preparação depende das consultas. Só métricas agregadas são registradas nos logs.'],
 'supabase/functions/assistente-operacional/catalogo-assistente.mjs':['Normalização limitada de termos, aproximação apenas para serviços, busca ampliada em até três palavras.','Mantido: não baixa o catálogo inteiro. Não transformar aproximação de nome em compatibilidade de peça.'],
 'supabase/functions/assistente-operacional/aplicacao-automotiva.mjs':['Consultas independentes em paralelo, resultados deduplicados por ID e seleção pela aplicação conhecida.','Mantido: restringe o automotivo e mantém inferências como sugestões editáveis; preço não determina a escolha.'],
 'supabase/functions/assistente-operacional/protocolo.mjs':['Schemas fechados, validação fora do modelo, cache por turno, leituras paralelas e preparação serializada; confirmar continua na interface.','Mantido: já evita uma rodada de modelo por item. Limites de ferramentas/rodadas impedem laços sem fim; nenhuma ferramenta do modelo confirma pagamento.'],
 'package.json':['Dependências e scripts de desenvolvimento, build e validação conferidos.','Mantido neste complemento: atualizar versões sem uma necessidade identificada aumentaria a superfície de regressão. As versões instaladas foram usadas nos testes.'],
 'vite.config.ts':['Entradas limitadas do prebundle, chunks, proxy validado, exclusão de artefatos e geração de cache offline.','Estado conferido: prefetch limitado a três trabalhadores, reutilização de assets com hash e fallback de rede para HTML; APIs não entram no cache de documentos. Não há snapshot inicial deste arquivo neste anexo.'],
 'vercel.json':['Rewrites e cabeçalhos de cache por tipo de conteúdo.','Mantido neste complemento: assets com hash são imutáveis, HTML/SW revalidam e conteúdo privado não recebe cache público. Configuração revisada localmente, sem publicação.'],
 'index.html':['Entrada única, idioma e metadados, favicon Pátio.','Mantido: sem novo script bloqueante ou dependência externa de interface.'],
 'eslint.config.js':['Regras de TypeScript, React e hooks.','Mantido: problemas foram corrigidos sem desabilitar regras de hooks para obter aprovação.'],
 'tsconfig.json':['Referências separadas de aplicação e ferramentas.','Mantido: evita misturar o ambiente DOM com o ambiente de configuração Node.'],
 'tsconfig.app.json':['Configuração de tipos da aplicação e verificação estática.','Mantido: a checagem final passou sem reduzir a rigidez do compilador.'],
 'tsconfig.node.json':['Configuração de tipos de ferramentas/build.','Mantido: separação de runtime preservada; build testado com Node 22.'],
 '.github/workflows/validacao.yml':['CI com permissão de leitura, Node 22, npm ci, validação e artefatos.','Mantido: timeout de 35 minutos limita execução; não inclui segredos nos relatórios de teste. Não foi disparado novo job remoto.'],
 'public/manifest.webmanifest':['PWA com escopo raiz e ícone local; não inclui scripts externos.','Mantido: compatível com abertura instalada e cache offline; personalizar o nome por ramo não é parte da correção de velocidade.'],
 'public/patio.svg':['Favicon vetorial pequeno usado por index.html.','Mantido: desenho local simples, sem recurso externo ou trabalho de JavaScript.'],
 'public/icone-patio.svg':['Ícone vetorial usado no manifesto instalável.','Mantido: preserva identidade e finalidade any/maskable; sem custo de rede externa.'],
 'public/favicon.svg':['Asset legado sem referência encontrada em src/index/manifest. XML e referências internas conferidos.','Mantido neste complemento: não é baixado na abertura medida; removê-lo durante comparação não melhora tempo de interação. Revisão estrutural do SVG, não redesenho de seus paths.'],
 'public/icons.svg':['Sprite legado sem referência encontrada em src/index/manifest, com símbolos e referências locais.','Mantido neste complemento: não participa do carregamento medido. Revisão estrutural de markup e referências; não tratado como componente React executado.'],
};
const edges=(await readdir('supabase/functions',{recursive:true})).filter(f=>/\.(ts|mjs)$/.test(f)).map(f=>'supabase/functions/'+f.replaceAll('\\','/'));
assert.equal(edges.length,23);assert(edges.every(f=>notas[f]));
const sha=b=>createHash('sha256').update(b).digest('hex');
const registros=[];for(const [arquivo,[antes,depois]] of Object.entries(notas)){
 const b=await readFile(arquivo);registros.push({arquivo,antes,depois,sha256:sha(b),bytes:b.length});
}
const teste=JSON.parse(await readFile(root+'/fotos-lote.json','utf8'));assert(teste.resultados.every(r=>r.ok));
const dados={escopo:'Complemento da revisão de src: 23 arquivos de Edge Functions, build/configuração e assets públicos. Revisão manual de código e estrutura. Não equivale a ensaio remoto de pagamentos, IA ou envio de mensagens. Estado de configuração registrado ao encerrar; quando não há snapshot inicial isso é declarado.',publicacao:'Alteração de fotos-proposta somente local; ainda não implantada no Supabase.',registros,testes:teste.resultados.length};
await writeFile(root+'/revisao.json',JSON.stringify(dados,null,2));
const e=x=>String(x).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
const rows=registros.map(r=>`<article><h2>${e(r.arquivo)}</h2><p><b>Antes / estado observado:</b> ${e(r.antes)}</p><p><b>Depois / decisão:</b> ${e(r.depois)}</p><small>SHA256: ${r.sha256}</small></article>`).join('');
await writeFile(root+'/relatorio.html',`<!doctype html><html lang="pt-BR"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Servidor e configuração · revisão integral</title><style>body{font:16px/1.6 system-ui;background:#f3f6f7;color:#18313c;margin:0}main{max-width:1050px;padding:24px;margin:auto}article{padding:20px;background:white;border:1px solid #cfdbdf;border-radius:10px;margin:18px 0}h1{font-size:32px}h2{font-size:18px;overflow-wrap:anywhere}small{overflow-wrap:anywhere}.aviso{padding:20px;background:#fff1cf;border-radius:8px}a{color:#125b73}</style><main><a href="../relatorio.html">Voltar ao relatório principal</a><h1>Servidor, build e configuração</h1><p>${e(dados.escopo)}</p><p class="aviso">${e(dados.publicacao)} Nenhuma cobrança, mensagem externa ou chamada paga de IA foi executada.</p><p>${registros.length} arquivos conferidos. Fotos: ${teste.resultados.length} casos aprovados, com handler real e dependências simuladas. Em uma galeria de 20 fotos, as chamadas de assinatura caem de 20 para 1; isso é contagem de requisições, não uma medição de latência em produção. <a href="fotos-lote.json">Evidência</a> · <a href="revisao.json">Todos os registros</a> · <a href="https://supabase.com/docs/reference/javascript/storage-from-createsignedurls">Contrato oficial de assinatura em lote</a>.</p>${rows}</main></html>`);
console.log(JSON.stringify({arquivos:registros.length,edge:edges.length,casos:teste.resultados.length}));
